import requests, json, sys

webhook_url = "https://open.feishu.cn/open-apis/bot/v2/hook/39ace5b8-ddf6-4ccf-8912-2c2681c618a4"

card = {
    "msg_type": "interactive",
    "card": {
        "header": {
            "title": {
                "tag": "plain_text",
                "content": "✅ 澳洲冰箱新品监控日报 - 2026-07-08"
            },
            "template": "blue"
        },
        "elements": [
            {
                "tag": "div",
                "text": {
                    "tag": "lark_md",
                    "content": "**今日 5 品牌均无新品上架或状态变更。**\n\n---\n\n**📊 各品牌状态：**\n\n🔵 **海信 Hisense** — 无变化\n· 官网产品列表正常，所有型号与基线一致\n· HRCD483TS/HRCD483TSW/HRTF325S（7月7日新增）仍在售\n\n🔵 **美的 Midea** — 无变化\n· 官网 15 款产品全部在基线中\n· 3 款 Coming Soon（MDRT580MTF45AP 413L / MDRS925FIM45AP 700L / MDRF923FIM45AP 706L）仍为 Coming Soon\n\n🔵 **三星 Samsung** — 无变化\n· 搜索未发现 AU 市场新冰箱型号\n\n🔵 **LG** — 无变化\n· 搜索未发现 AU 市场新冰箱型号\n\n🔵 **西屋 Westinghouse** — 无变化\n· 官网 75 款产品，型号与基线一致\n\n---\n\n**重点关注：**\n· 美的 3 款 Coming Soon 型号待上线\n· 海信 2026 新品（5 款 ⭐New）持续监控中"
                }
            },
            {
                "tag": "hr"
            },
            {
                "tag": "note",
                "elements": [
                    {
                        "tag": "plain_text",
                        "content": "由 Incaier Agent 自动监控 | 下次汇总：明天下午 3:07"
                    }
                ]
            }
        ]
    }
}

resp = requests.post(webhook_url, json=card, timeout=30)
result = {"status_code": resp.status_code, "body": resp.json()}
with open(sys.argv[-1], 'w', encoding='utf-8') as f:
    json.dump(result, f, ensure_ascii=False, indent=2)
print("Feishu response:", resp.status_code, resp.json())

